def canBecomePalindrome(vals, succ):
    a = []
    cur = 0
    while cur != -1:
        a.append(vals[cur])
        cur = succ[cur]

    def is_pal(i, j):
        while i < j:
            if a[i] != a[j]:
                return False
            i += 1
            j -= 1
        return True

    i, j = 0, len(a) - 1
    while i < j:
        if a[i] != a[j]:
            return is_pal(i + 1, j) or is_pal(i, j - 1)
        i += 1
        j -= 1
    return True
